def solve_small_n_refined(N):
    best_sum = -float('inf')
    for path in range(1 << N):
        a = [0] * (N + 1)
        b = [0] * (N + 1)
        a[0] = 1
        b[0] = 1
        for i in range(N):
            if (path >> i) & 1:
                a[i+1] = 2 * a[i]
                b[i+1] = b[i]**2
            else:
                a[i+1] = a[i]
                b[i+1] = 2 * b[i]

        count_R2 = 0
        for i in range(N):
            if not ((path >> i) & 1): count_R2 += 1

        def S_func(u):
            res = count_R2
            for n in range(N):
                if (path >> n) & 1:
                    res += u**a[n]/b[n]
                else:
                    res -= u**a[n]/b[n]
            return res

        limit = float('inf')
        if a[N] > 1:
            limit = b[N]**(1.0/(a[N]-1))

        if limit == float('inf'):
            # All R2s were used, or something like that.
            # S_func(u) = N - \sum_{n \in R2} u^a_n / b_n
            # Since all a_n >= 1 and b_n > 0, this is maximized at u=0.
            # Wait, a_n could be 1.
            # If any a_n = 1, and it's an R2 step, S_func(u) = N - u/b_n - ...
            # So u=0 is the max.
            best_sum = max(best_sum, S_func(0))
        else:
            # Sample and find max
            grid = np.linspace(0, limit, 2000)
            vals = [S_func(u) for u in grid]
            best_sum = max(best_sum, max(vals))

    return best_sum / 4.0

