import sympy as sp

def solve_for_N_detailed(N):
    results = []
    for i in range(1 << N):
        choices = []
        for j in range(N):
            choices.append(1 if (i & (1 << j)) else 2)

        x0 = sp.Symbol('x0')
        x = x0
        total_y = 0
        for c in choices:
            if c == 1:
                total_y += x
                x = 4 * x**2
            else:
                total_y += 0.25 - x
                x = x / 2

        xN = x
        f = xN - x0
        roots = sp.solve(f, x0)
        real_roots = [r.evalf() for r in roots if r.is_real]
        real_roots = sorted(list(set(real_roots)))
        points = [0] + real_roots + [10]
        points = sorted(list(set([p for p in points if p >= 0])))

        best_seq_sum = -float('inf')
        for j in range(len(points) - 1):
            mid = (points[j] + points[j+1]) / 2
            if f.subs(x0, mid) <= 0:
                d_y = sp.diff(total_y, x0)
                crit_points = sp.solve(d_y, x0)
                test_points = [points[j], points[j+1]]
                for cp in crit_points:
                    if cp.is_real and points[j] <= cp.evalf() <= points[j+1]:
                        test_points.append(cp.evalf())
                for tp in test_points:
                    val = float(total_y.subs(x0, tp))
                    if val > best_seq_sum:
                        best_seq_sum = val
        results.append((choices, best_seq_sum))
    return results

